trial.program_source:
def transform(grid):
    out=[r[:] for r in grid]
    h=len(grid)
    for c in range(len(grid[0])):
        start=next((r for r in range(h) if grid[r][c]!=0),h)
        r=start
        while r<h and grid[r][c]==1:
            r+=1
        if r<h and grid[r][c]==3:
            for y in range(start,r):
                out[y][c]=3
    return out

